    image_patch = ImagePatch(image)
    horse_patches = image_patch.find("horse")
    mane_patches = image_patch.find("mane")
    water_patches = image_patch.find("water")

    if not horse_patches or not mane_patches or not water_patches:
        return image_patch

    horse = max(horse_patches, key=lambda h: h.verify_property("horse", "light brown mane"))
    water_in_face = [w for w in water_patches if w.overlaps_with(*horse.bbox)]

    if not water_in_face:
        return horse

    return min(water_in_face, key=lambda w: w.distance(horse))

